class Solution {
public:
    int findBlackPixel(vector<vector<char>>& picture, int target) {
        int m = picture.size(), n = picture[0].size();
        unordered_map<string, int> frequency;
        vector<int> blackInColumn(n, 0);
        for (const auto& row : picture) {
            string pattern(row.begin(), row.end());
            ++frequency[pattern];
            for (int c = 0; c < n; ++c) {
                blackInColumn[c] += row[c] == 'B';
            }
        }
        int answer = 0;
        for (const auto& entry : frequency) {
            if (entry.second != target ||
                count(entry.first.begin(), entry.first.end(), 'B') != target) {
                continue;
            }
            for (int c = 0; c < n; ++c) {
                if (entry.first[c] == 'B' && blackInColumn[c] == target) {
                    answer += target;
                }
            }
        }
        return answer;
    }
};
